import {validatePost,commitment,filterPosts} from './model.mjs';
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples=[{id:'demo-1',name:'Minh Anh',city:'TP. Hồ Chí Minh',category:'Sinh hoạt',title:'Một khoảng thở để bắt đầu lại.',story:'Sau khi mất việc, mình dùng khoản vay nhỏ để trang trải tiền nhà và sinh hoạt cho hai mẹ con. Mình đã có công việc mới, nhưng khoản nợ cũ vẫn khiến mỗi tháng trở nên chật vật.\n\nMình đang cố gắng từng ngày. Một chút đồng hành lúc này sẽ giúp mình ổn định lại cuộc sống và có thời gian dành cho con.',amount:18500000,pledged:0,sample:true},{id:'demo-2',name:'Hoàng Nam',city:'Đà Nẵng',category:'Y tế',title:'Để ba yên tâm tiếp tục điều trị.',story:'Chi phí điều trị của ba đến bất ngờ, mình phải vay để lo viện phí. Mình đang làm thêm ngoài giờ để trả dần, nhưng vẫn cần một chút giúp đỡ để vượt qua giai đoạn này.',amount:32000000,pledged:0,sample:true},{id:'demo-3',name:'Thu Hà',city:'Hà Nội',category:'Học tập',title:'Mình muốn viết tiếp giấc mơ giảng đường.',story:'Mình là sinh viên năm cuối, vừa học vừa làm để tự trang trải. Khoản vay học phí là điều mình đang lo nhất. Mình mong có thể hoàn thành kỳ học cuối và tìm một công việc ổn định.',amount:12000000,pledged:0,sample:true},{id:'demo-4',name:'Quốc Bảo',city:'Cần Thơ',category:'Sinh hoạt',title:'Dựng lại góc sửa xe nhỏ của mình.',story:'Tiệm sửa xe nhỏ là nguồn thu nhập chính của gia đình. Sau một thời gian phải nghỉ việc vì tai nạn, mình đang quay lại làm và cần giải quyết khoản nợ sinh hoạt tích lại.',amount:9500000,pledged:0,sample:true}];
const initial=()=>({posts:structuredClone(samples),saved:[],skipped:[],pledges:[],role:'Bros'});let state=initial(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('debtfreelately-v1'));if(raw&&Array.isArray(raw.posts)&&Array.isArray(raw.saved)&&Array.isArray(raw.skipped)&&Array.isArray(raw.pledges)){state=raw;state.posts=raw.posts.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.title==='string'&&typeof p.story==='string'&&Number.isFinite(p.amount)&&Number.isFinite(p.pledged));}}catch{storageOK=false;}
let view='discover',category='Tất cả',query='',lastSkipped=null,current=null;const categories=['Tất cả','Sinh hoạt','Y tế','Học tập','Khác'];
function persist(){try{localStorage.setItem('debtfreelately-v1',JSON.stringify(state));return true;}catch{storageOK=false;toast('Không lưu được trên thiết bị. Thay đổi chỉ tồn tại trong phiên này.');return false;}}
let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}function close(){$('#modal').close();}$('#close-modal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function filtered(){return filterPosts(state.posts,{category,query,skipped:state.skipped}).filter(p=>!p.mine&&p.pledged<p.amount);}
function empty(title,text,button='',action=''){return `<div class="empty"><div class="symbol">✳</div><h2>${title}</h2><p>${text}</p>${button?`<button class="dark" data-action="${action}">${button}</button>`:''}</div>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#saved-count').textContent=state.saved.length;$('#role-name').textContent=state.role==='Bros'?'Bạn là một Bro':'Bạn là Broke';$('#categories').innerHTML=categories.map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('');$('.toolbar').hidden=view!=='discover'&&view!=='saved';const titles={discover:['Một lần quẹt.<br><span>Một khởi đầu mới.</span>','Phía sau mỗi khoản nợ là một câu chuyện. Lắng nghe, kết nối<br class="desktop"> và giúp ai đó bước tiếp — theo cách của bạn.'],saved:['Những câu chuyện<br><span>bạn muốn giữ lại.</span>','Một kết nối nhỏ hôm nay có thể trở thành sự đồng hành ngày mai.'],pledges:['Sự tử tế,<br><span>được ghi nhận.</span>','Theo dõi cam kết của bạn. Chưa có tiền được chuyển qua ứng dụng.'],mine:['Câu chuyện của bạn.<br><span>Một cơ hội mới.</span>','Chia sẻ điều bạn đang trải qua và quản lý các bài đăng của mình.']};$('#page-title').innerHTML=titles[view][0];$('#page-description').innerHTML=titles[view][1];
if(view==='discover')renderDeck();if(view==='saved')renderList(state.posts.filter(p=>state.saved.includes(p.id)&&(category==='Tất cả'||p.category===category)&&`${p.title} ${p.name} ${p.story}`.toLowerCase().includes(query.toLowerCase())),'saved');if(view==='mine')renderList(state.posts.filter(p=>p.mine),'mine');if(view==='pledges')renderPledges();}
function renderDeck(){const posts=filtered();current=posts[0];if(!current){$('#content').innerHTML=empty('Bạn đã xem hết rồi!','Thử đổi bộ lọc hoặc xem lại các câu chuyện đã bỏ qua.','Xem lại các thẻ','reset');return;}const p=current,percent=Math.min(100,Math.round(p.pledged/p.amount*100));$('#content').innerHTML=`<div class="deck-label"><span>CÂU CHUYỆN ĐANG CHỜ BẠN</span><span>${posts.length} câu chuyện · <button class="detail-link" data-action="undo" ${lastSkipped?'':'disabled'}>↶ Hoàn tác</button></span></div><article class="story-card" id="swipe-card"><div class="card-art ${p.category==='Y tế'?'medical':p.category==='Học tập'?'education':''}"><span class="art-caption">EVERY STORY DESERVES A NEW CHAPTER.</span><div class="art-sun"></div><div class="art-hill"></div><div class="art-hill second"></div><div class="art-door"></div><span class="category-badge">${esc(p.category)}</span><span class="sample-badge">${p.sample?'Hồ sơ mẫu':'Chưa xác minh'}</span></div><div class="card-body"><div class="person"><div class="avatar">${esc(p.name.charAt(0))}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.city||'Chưa cung cấp địa điểm')} · ${p.sample?'Dữ liệu minh họa':'Tự chia sẻ'}</small></div></div><h2>${esc(p.title)}</h2><p class="story-text">${esc(p.story.length>170?p.story.slice(0,170)+'…':p.story)}</p><button class="detail-link" data-action="detail" data-id="${esc(p.id)}">Đọc toàn bộ câu chuyện ↗</button><div class="amounts"><div><small>KHOẢN NỢ CẦN ĐƯỢC GIÚP</small><strong>${money(p.amount)}</strong></div><span>${percent}% được cam kết</span></div><div class="progress"><div style="width:${percent}%"></div></div><div class="progress-caption"><span>${money(p.pledged)} cam kết</span><span>Chưa thanh toán</span></div></div></article><div class="actions"><button data-action="skip" title="Bỏ qua" aria-label="Bỏ qua câu chuyện">×</button><button class="support" data-action="help" data-id="${esc(p.id)}" title="Tôi muốn giúp" aria-label="Cam kết hỗ trợ">♡</button><button data-action="save" data-id="${esc(p.id)}" class="${state.saved.includes(p.id)?'saved':''}" title="Lưu câu chuyện" aria-label="Lưu câu chuyện">${state.saved.includes(p.id)?'★':'☆'}</button></div><p class="gesture-tip">← Bỏ qua &nbsp; · &nbsp; Quẹt phải để giúp →<br>Bạn luôn được xác nhận số tiền trước khi cam kết.</p>`;const card=$('#swipe-card');let start=null;card.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};});card.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5){if(dx<0)skip();else help(p.id);}});card.addEventListener('pointercancel',()=>start=null);}
function renderList(posts,kind){if(!posts.length){$('#content').innerHTML=empty(kind==='mine'?'Câu chuyện của bạn bắt đầu ở đây.':'Chưa có câu chuyện nào. ',kind==='mine'?'Đăng bài bằng biệt danh. Không chia sẻ số tài khoản hoặc giấy tờ cá nhân.':'Nhấn ngôi sao trên thẻ để lưu một câu chuyện.',kind==='mine'?'Viết câu chuyện':'Khám phá ngay',kind==='mine'?'new':'discover');return;}$('#content').innerHTML=posts.map(p=>`<article class="list-card"><small>${esc(p.category)} · ${p.sample?'Hồ sơ mẫu':'Chưa xác minh'}</small><h3>${esc(p.title)}</h3><small>${esc(p.name)}</small><div class="row"><strong>${money(p.amount)}</strong><button class="text-button" data-action="detail" data-id="${esc(p.id)}">Xem câu chuyện ↗</button></div><div class="progress"><div style="width:${Math.min(100,p.pledged/p.amount*100)}%"></div></div><small>${money(p.pledged)} cam kết · Chưa thanh toán</small><div class="row">${kind==='mine'?`<button class="text-button" data-action="edit" data-id="${esc(p.id)}">Sửa bài</button><button class="text-button danger" data-action="delete" data-id="${esc(p.id)}">Xóa bài</button>`:`<button class="text-button" data-action="save" data-id="${esc(p.id)}">Bỏ lưu</button><button class="dark" data-action="help" data-id="${esc(p.id)}">Tôi muốn giúp ♡</button>`}</div></article>`).join('');}
function renderPledges(){if(!state.pledges.length){$('#content').innerHTML=empty('Một chút giúp đỡ, một ý nghĩa lớn.','Cam kết bạn xác nhận sẽ xuất hiện ở đây.<br>Đây chưa phải khoản tiền đã gửi.','Tìm câu chuyện','discover');return;}$('#content').innerHTML=`<div class="stats"><div class="stat"><small>Tổng cam kết</small><strong>${money(state.pledges.reduce((s,p)=>s+p.amount,0))}</strong></div><div class="stat"><small>Số lần đồng hành</small><strong>${state.pledges.length}</strong></div></div>`+state.pledges.map(p=>`<article class="list-card"><small>${new Date(p.date).toLocaleDateString('vi-VN')} · Chưa thanh toán</small><h3>${esc(p.title)}</h3><div class="row"><strong>${money(p.amount)}</strong><button class="text-button danger" data-action="cancel" data-id="${esc(p.id)}">Hủy cam kết</button></div></article>`).join('');}
function skip(){if(!current)return;lastSkipped=current.id;state.skipped.push(current.id);persist();const card=$('#swipe-card');card?.classList.add('out-left');setTimeout(render,200);}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();}
function detail(id){const p=state.posts.find(p=>p.id===id);if(!p)return;modal(`<div class="eyebrow">${esc(p.category)} · ${p.sample?'HỒ SƠ MẪU':'CHƯA XÁC MINH'}</div><h2>${esc(p.title)}</h2><p>${esc(p.name)} · ${esc(p.city||'Chưa cung cấp địa điểm')}</p><p class="detail-story">${esc(p.story)}</p><div class="info-box">Khoản nợ: <strong>${money(p.amount)}</strong><br>Cam kết: ${money(p.pledged)} · Chưa thanh toán</div>${p.sample?'<p>Câu chuyện minh họa để trải nghiệm ứng dụng, không đại diện cho lời kêu gọi thật.</p>':''}<button class="dark" id="detail-help">${p.mine?'Đóng':'Tôi muốn đồng hành ♡'}</button>`);$('#detail-help').onclick=()=>{close();if(!p.mine)help(id);};}
function help(id){const p=state.posts.find(p=>p.id===id);if(!p)return;const remaining=p.amount-p.pledged;if(remaining<=0){toast('Câu chuyện này đã đủ cam kết.');return;}modal(`<div class="eyebrow">MỘT CHÚT ĐỒNG HÀNH</div><h2>Bạn muốn giúp ${esc(p.name)}?</h2><p>${esc(p.title)}</p><div class="info-box">Còn cần cam kết: <strong>${money(remaining)}</strong><br>${p.sample?'Đây là hồ sơ mẫu. ':''}Chỉ ghi nhận ý định hỗ trợ. Không thu hoặc chuyển tiền.</div><form id="pledge-form"><label for="pledge-amount">Số tiền bạn muốn cam kết (VNĐ)</label><input id="pledge-amount" name="amount" type="number" min="1000" max="${remaining}" step="1000" value="${Math.min(100000,remaining)}" required><div class="form-error" id="form-error" role="alert"></div><button class="dark">Xác nhận cam kết · Chưa thanh toán</button></form>`);$('#pledge-form').onsubmit=e=>{e.preventDefault();try{const amount=Number(new FormData(e.target).get('amount'));const updated=commitment(p,amount);state.posts=state.posts.map(x=>x.id===id?updated:x);state.pledges.push({id:crypto.randomUUID(),postId:id,title:p.title,amount,date:new Date().toISOString()});persist();close();render();toast('Đã ghi nhận cam kết. Chưa có tiền được chuyển.');}catch(error){$('#form-error').textContent=error.message;}};}
function postForm(id){const p=state.posts.find(p=>p.id===id)||{};modal(`<div class="eyebrow">DÀNH CHO BROKE</div><h2>${id?'Chỉnh sửa câu chuyện':'Ai cũng có lúc cần một bàn tay.'}</h2><p>Chia sẻ bằng biệt danh. Bài đăng này chỉ được lưu trên trình duyệt của bạn trong bản thử nghiệm.</p><form id="post-form"><label for="post-name">Tên hiển thị / biệt danh</label><input id="post-name" name="name" maxlength="50" required value="${esc(p.name||'')}"><label for="post-city">Thành phố (không bắt buộc)</label><input id="post-city" name="city" maxlength="60" value="${esc(p.city||'')}"><label for="post-title">Tiêu đề câu chuyện</label><input id="post-title" name="title" maxlength="100" required value="${esc(p.title||'')}"><label for="post-category">Loại khoản nợ</label><select name="category" id="post-category">${categories.slice(1).map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select><label for="post-amount">Tổng khoản nợ (VNĐ)</label><input id="post-amount" name="amount" type="number" min="${Math.max(1000,p.pledged||0)}" max="1000000000000" step="1000" required value="${p.amount||''}"><label for="post-story">Câu chuyện của bạn</label><textarea id="post-story" name="story" maxlength="3000" required placeholder="Điều gì đã xảy ra và sự hỗ trợ sẽ giúp bạn thế nào?">${esc(p.story||'')}</textarea><div class="info-box">Không đăng CCCD, địa chỉ cụ thể, thông tin thẻ hoặc số tài khoản. Chức năng xác minh sẽ được bổ sung sau.</div><div id="form-error" class="form-error" role="alert"></div><button class="dark">${id?'Lưu thay đổi':'Đăng câu chuyện'}</button></form>`);$('#post-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);for(const k of ['name','city','title','story'])d[k]=d[k].trim();validatePost(d);if(d.amount<(p.pledged||0))throw Error('Số nợ không thể thấp hơn tổng cam kết.');if(id)state.posts=state.posts.map(x=>x.id===id?{...x,...d}:x);else state.posts.unshift({...d,id:crypto.randomUUID(),pledged:0,mine:true,sample:false});state.role='Broke';persist();view='mine';close();render();toast(id?'Đã lưu thay đổi.':'Đã lưu bài đăng trên thiết bị của bạn.');}catch(error){$('#form-error').textContent=error.message;}};}
function deletePost(id){const p=state.posts.find(p=>p.id===id&&p.mine);if(!p)return;modal(`<h2>Xóa câu chuyện này?</h2><p>${esc(p.title)}</p><p>Bài đăng sẽ bị xóa khỏi thiết bị này.</p><button id="confirm-delete" class="dark">Xóa bài đăng</button>`);$('#confirm-delete').onclick=()=>{state.posts=state.posts.filter(x=>x.id!==id);state.saved=state.saved.filter(x=>x!==id);persist();close();render();toast('Đã xóa bài đăng.');};}
function cancelPledge(id){const p=state.pledges.find(x=>x.id===id);if(!p)return;modal(`<h2>Hủy cam kết ${money(p.amount)}?</h2><p>${esc(p.title)}</p><p>Không có khoản tiền nào cần hoàn trả vì chưa thực hiện thanh toán.</p><button class="dark" id="confirm-cancel">Xác nhận hủy cam kết</button>`);$('#confirm-cancel').onclick=()=>{state.posts=state.posts.map(x=>x.id===p.postId?{...x,pledged:Math.max(0,x.pledged-p.amount)}:x);state.pledges=state.pledges.filter(x=>x.id!==id);persist();close();render();toast('Đã hủy cam kết.');};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-view],[data-category]');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.category){category=b.dataset.category;render();return;}const id=b.dataset.id;switch(b.dataset.action){case 'save':save(id);break;case 'detail':detail(id);break;case 'help':help(id);break;case 'skip':skip();break;case 'reset':state.skipped=[];lastSkipped=null;persist();render();break;case 'undo':if(lastSkipped){state.skipped=state.skipped.filter(x=>x!==lastSkipped);lastSkipped=null;persist();render();}break;case 'discover':view='discover';category='Tất cả';query='';$('#search').value='';render();break;case 'new':postForm();break;case 'edit':postForm(id);break;case 'delete':deletePost(id);break;case 'cancel':cancelPledge(id);}});
$('#search').oninput=e=>{query=e.target.value;render();};$('#new-post').onclick=()=>postForm();$('#role-toggle').onclick=()=>{state.role=state.role==='Bros'?'Broke':'Bros';view=state.role==='Broke'?'mine':'discover';persist();render();};$('#about').onclick=()=>modal(`<div class="eyebrow">WELCOME TO DEBTFREELATELY</div><h2>Cùng nhau nhẹ gánh.</h2><p><strong>Broke</strong> chia sẻ câu chuyện và khoản nợ. <strong>Bros</strong> quẹt thẻ để khám phá, lưu lại hoặc cam kết giúp một phần.</p><p>Quẹt trái để bỏ qua, quẹt phải để mở xác nhận hỗ trợ. Trên máy tính, bạn cũng có thể dùng phím mũi tên.</p><div class="info-box">Bản thử nghiệm: dữ liệu chỉ lưu tại trình duyệt này, chưa đồng bộ giữa người dùng. Không có đăng nhập, xác minh hoặc thanh toán thật. Hồ sơ mẫu được ghi rõ trên thẻ.</div><p>Cam kết có thể hủy trong mục “Cam kết của tôi”. Bài viết có thể sửa hoặc xóa trong “Bài đăng của tôi”.</p>`);
document.addEventListener('keydown',e=>{if($('#modal').open||e.target.matches('input,textarea,select')||view!=='discover')return;if(e.key==='ArrowLeft'){e.preventDefault();skip();}if(e.key==='ArrowRight'&&current){e.preventDefault();help(current.id);}});render();if(!storageOK)toast('Bộ nhớ trình duyệt không khả dụng; dữ liệu chỉ tồn tại trong phiên này.');
